"""Generate govn/engine/src/tables.rs from UniKey ukengine sources, so data is not retyped by hand.

usage: gen_tables.py <ukengine_dir> <output.rs>
"""
import pathlib
import re
import sys

src_dir = pathlib.Path(sys.argv[1])
out_path = pathlib.Path(sys.argv[2])


def clean(s):
    return re.sub(r"//[^\n]*|/\*.*?\*/", " ", s, flags=re.S)


lexi = clean((src_dir / "vnlexi.h").read_text("latin1"))
eng = clean((src_dir / "ukengine.cpp").read_text("latin1"))
data = clean((src_dir / "data.cpp").read_text("latin1"))
out = [
    "// @generated by tools/gen_tables.py from UniKey ukengine (vnlexi.h, ukengine.cpp, data.cpp).",
    "// Copyright (C) 2000-2005 Pham Kim Long. Do not edit by hand.",
    "#![allow(non_upper_case_globals, dead_code)]",
    "",
]

# enums keep the original C names, so the port can be read side by side with ukengine.cpp
for em in re.finditer(r"enum\s+(\w+)\s*\{(.*?)\}", lexi, re.S):
    v = 0
    for item in em.group(2).split(","):
        item = item.strip()
        if not item:
            continue
        if "=" in item:
            name, val = [x.strip() for x in item.split("=")]
            v = int(val, 0)
        else:
            name = item
        out.append(f"pub const {name}: i32 = {v};")
        v += 1
    out.append("")


def body(src, name):
    m = re.search(r"\b" + name + r"\s*(\[[^\]]*\]\s*)+=", src)
    i = src.index("{", m.end())
    d, j = 0, i
    while True:
        d += {"{": 1, "}": -1}.get(src[j], 0)
        j += 1
        if d == 0:
            return src[i + 1:j - 1]


def rows(text):
    res, d, cur = [], 0, ""
    for ch in text:
        if ch == "{":
            if d == 0:
                cur = ""
                d = 1
                continue
            d += 1
        elif ch == "}":
            d -= 1
            if d == 0:
                res.append(cur)
                continue
        if d >= 1:
            cur += ch
    return res


TK = r"-?\b\w+\b"
vs = rows(body(eng, "VSeqList"))
out.append("#[derive(Clone, Copy, Debug)]\npub struct VowelSeqInfo {\n    pub len: i32,\n    pub complete: bool,\n    pub con_suffix: bool,\n"
           "    pub v: [i32; 3],\n    pub sub: [i32; 3],\n    pub roof_pos: i32,\n    pub with_roof: i32,\n    pub hook_pos: i32,\n    pub with_hook: i32,\n}\n")
out.append(f"pub static VSEQ_LIST: [VowelSeqInfo; {len(vs)}] = [")
for r in vs:
    t = re.findall(TK, r)
    assert len(t) == 13, r
    out.append(
        f"    VowelSeqInfo {{ len: {t[0]}, complete: {'true' if t[1] != '0' else 'false'}, con_suffix: {'true' if t[2] != '0' else 'false'}, "
        f"v: [{t[3]}, {t[4]}, {t[5]}], sub: [{t[6]}, {t[7]}, {t[8]}], roof_pos: {t[9]}, with_roof: {t[10]}, hook_pos: {t[11]}, with_hook: {t[12]} }},")
out.append("];\n")

cs = rows(body(eng, "CSeqList"))
out.append("#[derive(Clone, Copy, Debug)]\npub struct ConSeqInfo {\n    pub len: i32,\n    pub c: [i32; 3],\n    pub suffix: bool,\n}\n")
out.append(f"pub static CSEQ_LIST: [ConSeqInfo; {len(cs)}] = [")
for r in cs:
    t = re.findall(TK, r)
    assert len(t) == 5, r
    out.append(f"    ConSeqInfo {{ len: {t[0]}, c: [{t[1]}, {t[2]}, {t[3]}], suffix: {t[4]} }},")
out.append("];\n")

pairs = re.findall(r"\{\s*(\w+)\s*,\s*(\w+)\s*\}", body(eng, "VCPairList"))
out.append(f"pub static VC_PAIR_LIST: [(i32, i32); {len(pairs)}] = [")
for i in range(0, len(pairs), 6):
    out.append("    " + " ".join(f"({a}, {b})," for a, b in pairs[i:i + 6]))
out.append("];\n")


def nums(name, n):
    v = [int(x, 0) for x in re.findall(r"0[xX][0-9a-fA-F]+|\b\d+\b", body(data, name))]
    assert len(v) == n, (name, len(v))
    return v


for name, rust, ty in [("UnicodeTable", "UNICODE_TABLE", "u16"), ("StdVnRootChar", "STD_VN_ROOT_CHAR", "i32"), ("StdVnNoTone", "STD_VN_NO_TONE", "i32")]:
    v = nums(name, 213)
    out.append(f"pub static {rust}: [{ty}; 213] = [")
    for i in range(0, 213, 12):
        out.append("    " + " ".join((f"{x:#06x}," if ty == "u16" else f"{x},") for x in v[i:i + 12]))
    out.append("];\n")

out_path.parent.mkdir(parents=True, exist_ok=True)
out_path.write_text("\n".join(out) + "\n", encoding="utf-8")
print("wrote", out_path, "vseq", len(vs), "cseq", len(cs), "vc", len(pairs))
